module bandwidth_allocator(\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] a0,\n    input [31:0] a1,\n    input [31:0] a2,\n    input [31:0] a3,\n    input [31:0] b0,\n    input [31:0] b1,\n    input [31:0] b2,\n    input [31:0] b3,\n    input [31:0] d0,\n    input [31:0] d1,\n    input [31:0] d2,\n    input [31:0] d3,\n    input [31:0] t,\n    output reg [31:0] x0,\n    output reg [31:0] x1,\n    output reg [31:0] x2,\n    output reg [31:0] x3,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] COMPUTE_TOTAL_D = 4'd1;\n    localparam [3:0] COMPUTE_Y = 4'd2;\n    localparam [3:0] INIT_X = 4'd3;\n    localparam [3:0] CHECK_ITERATION = 4'd4;\n    localparam [3:0] COMPUTE_RESIDUAL = 4'd5;\n    localparam [3:0] COMPUTE_TOTAL_Y_FREE = 4'd6;\n    localparam [3:0] UPDATE_X = 4'd7;\n    localparam [3:0] DONE_STATE = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [1:0] index;\n    reg [31:0] total_d;\n    reg [31:0] y_0, y_1, y_2, y_3;\n    reg [31:0] x_0, x_1, x_2, x_3;\n    reg [3:0] fixed;\n    reg [31:0] residual;\n    reg [31:0] total_y_free;\n    reg changed;\n    reg [7:0] cycle_count;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            fixed <= 4'd0;\n            changed <= 1'b0;\n            index <= 2'd0;\n            total_d <= 32'd0;\n            residual <= 32'd0;\n            total_y_free <= 32'd0;\n            y_0 <= 32'd0; y_1 <= 32'd0; y_2 <= 32'd0; y_3 <= 32'd0;\n            x_0 <= 32'd0; x_1 <= 32'd0; x_2 <= 32'd0; x_3 <= 32'd0;\n            x0 <= 32'd0; x1 <= 32'd0; x2 <= 32'd0; x3 <= 32'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        total_d <= 32'd0;\n                        cycle_count <= 8'd0;\n                        next_state <= COMPUTE_TOTAL_D;\n                    end\n                end\n\n                COMPUTE_TOTAL_D: begin\n                    case (index)\n                        2'd0: total_d <= total_d + d0;\n                        2'd1: total_d <= total_d + d1;\n                        2'd2: total_d <= total_d + d2;\n                        2'd3: total_d <= total_d + d3;\n                    endcase\n\n                    if (index == 2'd3) begin\n                        next_state <= COMPUTE_Y;\n                        index <= 2'd0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                COMPUTE_Y: begin\n                    case (index)\n                        2'd0: y_0 <= (t * d0) / total_d;\n                        2'd1: y_1 <= (t * d1) / total_d;\n                        2'd2: y_2 <= (t * d2) / total_d;\n                        2'd3: y_3 <= (t * d3) / total_d;\n                    endcase\n\n                    if (index == 2'd3) begin\n                        next_state <= INIT_X;\n                        index <= 2'd0;\n                        fixed <= 4'd0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                INIT_X: begin\n                    case (index)\n                        2'd0: begin\n                            x_0 <= y_0;\n                            if (y_0 < a0) begin x_0 <= a0; fixed[0] <= 1'b1; end\n                            else if (y_0 > b0) begin x_0 <= b0; fixed[0] <= 1'b1; end\n                        end\n                        2'd1: begin\n                            x_1 <= y_1;\n                            if (y_1 < a1) begin x_1 <= a1; fixed[1] <= 1'b1; end\n                            else if (y_1 > b1) begin x_1 <= b1; fixed[1] <= 1'b1; end\n                        end\n                        2'd2: begin\n                            x_2 <= y_2;\n                            if (y_2 < a2) begin x_2 <= a2; fixed[2] <= 1'b1; end\n                            else if (y_2 > b2) begin x_2 <= b2; fixed[2] <= 1'b1; end\n                        end\n                        2'd3: begin\n                            x_3 <= y_3;\n                            if (y_3 < a3) begin x_3 <= a3; fixed[3] <= 1'b1; end\n                            else if (y_3 > b3) begin x_3 <= b3; fixed[3] <= 1'b1; end\n                        end\n                    endcase\n\n                    if (index == 2'd3) begin\n                        next_state <= CHECK_ITERATION;\n                        changed <= 1'b0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                CHECK_ITERATION: begin\n                    if (fixed == 4'b1111 || cycle_count > 8'd100) begin\n                        next_state <= DONE_STATE;\n                    end else begin\n                        residual <= t;\n                        next_state <= COMPUTE_RESIDUAL;\n                        index <= 2'd0;\n                    end\n                end\n\n                COMPUTE_RESIDUAL: begin\n                    case (index)\n                        2'd0: if (fixed[0]) residual <= residual - x_0;\n                        2'd1: if (fixed[1]) residual <= residual - x_1;\n                        2'd2: if (fixed[2]) residual <= residual - x_2;\n                        2'd3: if (fixed[3]) residual <= residual - x_3;\n                    endcase\n\n                    if (index == 2'd3) begin\n                        next_state <= COMPUTE_TOTAL_Y_FREE;\n                        total_y_free <= 32'd0;\n                        index <= 2'd0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                COMPUTE_TOTAL_Y_FREE: begin\n                    case (index)\n                        2'd0: if (!fixed[0]) total_y_free <= total_y_free + y_0;\n                        2'd1: if (!fixed[1]) total_y_free <= total_y_free + y_1;\n                        2'd2: if (!fixed[2]) total_y_free <= total_y_free + y_2;\n                        2'd3: if (!fixed[3]) total_y_free <= total_y_free + y_3;\n                    endcase\n\n                    if (index == 2'd3) begin\n                        next_state <= UPDATE_X;\n                        index <= 2'd0;\n                        changed <= 1'b0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                UPDATE_X: begin\n                    case (index)\n                        2'd0: if (!fixed[0]) begin\n                            x_0 <= (residual * y_0) / total_y_free;\n                            if (x_0 < a0) begin\n                                x_0 <= a0;\n                                fixed[0] <= 1'b1;\n                                changed <= 1'b1;\n                            end else if (x_0 > b0) begin\n                                x_0 <= b0;\n                                fixed[0] <= 1'b1;\n                                changed <= 1'b1;\n                            end\n                        end\n                        2'd1: if (!fixed[1]) begin\n                            x_1 <= (residual * y_1) / total_y_free;\n                            if (x_1 < a1) begin\n                                x_1 <= a1;\n                                fixed[1] <= 1'b1;\n                                changed <= 1'b1;\n                            end else if (x_1 > b1) begin\n                                x_1 <= b1;\n                                fixed[1] <= 1'b1;\n                                changed <= 1'b1;\n                            end\n                        end\n                        2'd2: if (!fixed[2]) begin\n                            x_2 <= (residual * y_2) / total_y_free;\n                            if (x_2 < a2) begin\n                                x_2 <= a2;\n                                fixed[2] <= 1'b1;\n                                changed <= 1'b1;\n                            end else if (x_2 > b2) begin\n                                x_2 <= b2;\n                                fixed[2] <= 1'b1;\n                                changed <= 1'b1;\n                            end\n                        end\n                        2'd3: if (!fixed[3]) begin\n                            x_3 <= (residual * y_3) / total_y_free;\n                            if (x_3 < a3) begin\n                                x_3 <= a3;\n                                fixed[3] <= 1'b1;\n                                changed <= 1'b1;\n                            end else if (x_3 > b3) begin\n                                x_3 <= b3;\n                                fixed[3] <= 1'b1;\n                                changed <= 1'b1;\n                            end\n                        end\n                    endcase\n\n                    if (index == 2'd3) begin\n                        if (changed) begin\n                            next_state <= COMPUTE_RESIDUAL;\n                        end else begin\n                            next_state <= DONE_STATE;\n                        end\n                        index <= 2'd0;\n                    end else begin\n                        index <= index + 2'd1;\n                    end\n                end\n\n                DONE_STATE: begin\n                    x0 <= x_0;\n                    x1 <= x_1;\n                    x2 <= x_2;\n                    x3 <= x_3;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule